/** The model's .claude/settings.json as this project gets it (before the toolkit's entries), or null. */
function modelSettingsFor(manifest, ctx) {
  const e = manifest.files.find((f) => f.model && f.target === '.claude/settings.json');
  if (!e || !entryApplies(e, ctx.config)) return null;
  const src = sourceText(e, ctx);
  if (src.skip) return null;
  try {
    return JSON.parse(src.text);
  } catch {
    return null;
  }
}

// ------------------------------------------------------------------ plan

/**
 * Plan the manifest for a project.
 * @param {{ root, mainRoot, config }} project  config is the intended .toolkit.json
 * @param {{ mode?: 'init'|'sync', pluginRoot?: string, env?: object, today?: string,
 *           changedSettings?: Array<{ key, from, to }>, manifest?: object }} [opts]
 */
export function planManifest(project, opts = {}) {
  const mode = opts.mode || 'sync';
  const env = opts.env || process.env;
  const pluginRoot = opts.pluginRoot || DEFAULT_PLUGIN_ROOT;
  const manifest = opts.manifest || loadManifest(pluginRoot);
  const config = project.config || {};
  // An unreadable hosts value stops the plan: guessing both hosts would
  // install the other host's files (for example .codex/) without a word.
  const { problem: hostsProblem } = readHosts(config);
  if (hostsProblem) {
    throw new ToolkitError(EXIT.INVALID, `${hostsProblem} Nothing was changed.`, { fix: HOSTS_FIX });
  }
  const installed = { ...((config && config.installed) || {}) };
  const ctx = {
    pluginRoot,
    config,
    conditions: manifest.conditions || {},
    today: opts.today || renderDate(config, env),
    sourceCache: new Map(),
    claudeOldPlugins: claudeOldPlugins(env),
    codexOldPlugins: codexOldPlugins(env),
  };
  ctx.modelSettings = modelSettingsFor(manifest, ctx);

  const byTarget = new Map();
  for (const e of manifest.files) {
    if (!byTarget.has(e.target)) byTarget.set(e.target, []);
    byTarget.get(e.target).push(e);
  }

  const targets = [];
  for (const [target, all] of byTarget) {
    const entries = all.filter((e) => entryInstalls(e, ctx));
    const abs = targetPath(target, project);
    const binary = entries.some((e) => e.binary);
    const before = readOrNull(abs, { binary });
    const execBits = entries.reduce((bits, e) => bits | (e.model ? (e.execBits || 0) : 0), 0);
    const t = { target, abs, entries, before, after: null, action: 'none', record: false, would: [], conflicts: [], notes: [], template: entries.some((e) => e.template), binary, execBits };
    targets.push(t);
    if (!entries.length) {
      if (before !== null && installed[target]) t.action = 'leftover';
      continue;
    }
    const recorded = installed[target] || null;
    const currentHash = before === null ? null : sha256(hashText(target, before));
    const status = before === null ? 'missing' : !recorded ? 'untracked' : currentHash === recorded ? 'unchanged' : 'changed';
    t.status = status;

    if (entries.some((e) => e.mode === 'seed')) {
      planSeed(t, ctx, project);
      continue;
    }

    try {
      if (before !== null && status !== 'unchanged' && entries.some((e) => e.mode === 'agents-md') && !hasSpan(before)) {
        // An AGENTS.md without the span markers is kept; the Toolkit V2 version goes to the proposal file.
        t.action = 'propose';
        t.proposal = compute(entries, null, ctx, target).text;
        t.notes.push(`kept the project's AGENTS.md; the Toolkit V2 version is in ${PROPOSAL_PATH}`);
      } else if (status === 'missing') {
        t.after = compute(entries, null, ctx, target).text;
        t.action = 'install';
        t.record = true;
      } else if (status === 'unchanged') {
        // The toolkit wrote this file, so the removals for the current setup
        // apply to it before the merge (a merge only adds).
        const base = applyRemovals(target, before, config, ctx.conditions).text;
        t.after = compute(entries, base, ctx, target).text;
        if (sameText(target, t.after, before)) {
          t.action = 'same';
          if (binary) t.after = before;
        } else {
          t.action = 'update';
        }
        t.record = true;
      } else if (status === 'untracked' && entries.some((e) => e.mode === 'agents-md')) {
        // Both span markers are there (the case without them is a proposal, above).
        planAdoptedAgents(t, ctx, before);
    else if (!w.ours) finding(findings, 'wrapper-foreign', 'computer', 'warning', `${w.path} exists but was not written by toolkit machine-setup.`, 'Ask the owner, then move it aside and run toolkit machine-setup.');
    else if (!onPath(path.dirname(w.path), env)) finding(findings, 'wrapper-path', 'computer', 'warning', `${path.dirname(w.path)} is not on the PATH, so the wrapper is not found by name.`, 'Add it to the PATH in the shell profile (ask the owner).');
  }
  const copies = installedPluginCopies('toolkit', env);
  const claude = copies.filter((c) => c.host === 'claude-code' && c.version).map((c) => c.version);
  const codex = copies.filter((c) => c.host === 'codex' && c.version).map((c) => c.version);
  if (claude.length && codex.length && !claude.some((v) => codex.includes(v))) {
    finding(findings, 'plugin-versions', 'computer', 'warning', `Claude Code runs toolkit ${claude.join(', ')} and Codex runs toolkit ${codex.join(', ')}. Two versions can write the tracker and memory differently.`, 'Update the older copy (claude plugin update toolkit@toolkit-v2, or codex plugin add toolkit@toolkit-v2), with the owner\'s yes.');
  }
}

// ------------------------------------------------------------------ scaffold

function checkScaffold(project, env, findings, { pluginRoot }) {
  // An unreadable hosts value is already reported (config-hosts); the plan cannot run until it is fixed.
  if (readHosts(project.config).problem) return null;
  let plan;
  try {
    plan = planManifest(project, { mode: 'sync', env, pluginRoot });
  } catch (err) {
    finding(findings, 'scaffold-plan', 'scaffold', 'problem', `The scaffold could not be checked: ${err.message}`, (err.details && err.details.fix) || 'Reinstall or update the toolkit plugin.');
    return null;
  }
  const by = (action) => plan.targets.filter((t) => t.action === action);
  const missing = by('install');
  if (missing.length) finding(findings, 'scaffold-missing', 'scaffold', 'problem', `${missing.length} scaffold file${missing.length === 1 ? ' is' : 's are'} missing: ${missing.map((t) => t.target).slice(0, 12).join(', ')}${missing.length > 12 ? ', ...' : ''}.`, 'Run toolkit sync.');
  const outdated = by('update');
  if (outdated.length) finding(findings, 'scaffold-outdated', 'scaffold', 'warning', `${outdated.length} scaffold file${outdated.length === 1 ? ' is' : 's are'} older than the toolkit's version and unchanged by the project: ${outdated.map((t) => t.target).join(', ')}.`, 'Run toolkit sync.');
  const agents = plan.targets.find((t) => t.target === 'AGENTS.md');
  if (agents && agents.spanOnly && !findings.some((f) => f.id === 'agents-md-span')) {
    finding(findings, 'agents-md-span', 'instructions', 'problem', 'The rules list in AGENTS.md does not match the files in .claude/rules/.', 'Run toolkit sync.');
  }
  for (const t of by('adopt')) {
    finding(findings, 'scaffold-adopt', 'scaffold', 'warning', `${t.target} has the Toolkit V2 sections, but the toolkit has not recorded it yet, so sync cannot tell later changes apart.`, 'Run toolkit sync.');
  }
  for (const t of by('conflict')) finding(findings, 'scaffold-conflict', 'scaffold', 'problem', t.conflicts.join(' '), `Fix ${t.target} by hand (define each setting one way only), then run toolkit sync.`);
The runtime reads the model's templates (`WORK-ITEM.md`, `DESIGN.md`, the
`.memory/` files, `DECISIONS.md`) from `scaffold/model/` through
`lib/core/templates.mjs`, never from a second copy.

## What installs

Every file in `scaffold/model/` installs at the same path, byte for byte,
unless a rule below changes it. A new file gets the model file's executable
bits. A model file that is not UTF-8 text (an image, for example) is copied as
bytes and hashed as bytes; it cannot have markers, a fill, or a removal rule,
and init stops with the file's name if one names it. After the model's files
come the toolkit's additions:

| Source | Target | Installs for | Mode |
| --- | --- | --- | --- |
| `templates/settings/claude-toolkit.json` | `.claude/settings.json` | Claude Code | `merge-json`, after the model's file |
| `templates/codex/config-base.toml` | `.codex/config.toml` | Codex | `merge-toml` |
| `templates/codex/toolkit.rules` | `.codex/rules/toolkit.rules` | Codex | `copy` |
| `templates/gitignore/toolkit.gitignore` | `.gitignore` | both hosts | `append`, after the model's file |

Targets under `.work-items/` and `.memory/` are written in the main checkout
(the folder that holds `git rev-parse --git-common-dir`), because both folders
are Git-ignored and shared by every worktree. Every other target is relative
to the project root (`git rev-parse --show-toplevel`).

